package org.humanjourney.core.geography.map;
import java.nio.file.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import com.electronwill.nightconfig.core.*;
import com.electronwill.nightconfig.core.file.CommentedFileConfig;
import org.humanjourney.core.geography.client.GeographyClientConfig;
import org.humanjourney.core.geography.map.client.*;
class MapPresentationConfigTest {
 @TempDir Path temp;
 @Test void freshConfigDefaultsToHoverAndApprovedStyles(){var c=CommentedConfig.inMemory();GeographyClientConfig.SPEC.correct(c);assertEquals("hover",c.get(MapConfigMigration.MODE));assertEquals(.25,GeographyClientConfig.MAP_OPACITY.getDefault());assertEquals(1D,GeographyClientConfig.MAP_WIDTH.getDefault());assertEquals(.4,GeographyClientConfig.MACRO_OPACITY.getDefault());assertEquals(1.5,GeographyClientConfig.MACRO_WIDTH.getDefault());assertEquals(.9,GeographyClientConfig.HOVER_LOCAL_OPACITY.getDefault());assertEquals(2D,GeographyClientConfig.HOVER_LOCAL_WIDTH.getDefault());assertEquals(.6,GeographyClientConfig.HOVER_MACRO_OPACITY.getDefault());assertEquals(2D,GeographyClientConfig.HOVER_MACRO_WIDTH.getDefault());}
 @Test void allModesValidateAndInvalidModeCorrectsToHover(){for(var mode:BoundaryMode.values()){var c=CommentedConfig.inMemory();c.set(MapConfigMigration.MODE,mode.id());GeographyClientConfig.SPEC.correct(c);assertEquals(mode.id(),c.get(MapConfigMigration.MODE));}for(Object bad:new Object[]{"bad","ALL",14,true}){var c=CommentedConfig.inMemory();c.set(MapConfigMigration.MODE,bad);GeographyClientConfig.SPEC.correct(c);assertEquals("hover",c.get(MapConfigMigration.MODE));}}
 @Test void legacyTrueMigratesToHover(){var c=CommentedConfig.inMemory();c.set(MapConfigMigration.LEGACY,true);assertTrue(MapConfigMigration.migrate(c));GeographyClientConfig.SPEC.correct(c);assertEquals("hover",c.get(MapConfigMigration.MODE));assertFalse(MapConfigMigration.migrate(c));}
 @Test void legacyFalseMigratesToOff(){var c=CommentedConfig.inMemory();c.set(MapConfigMigration.LEGACY,false);assertTrue(MapConfigMigration.migrate(c));GeographyClientConfig.SPEC.correct(c);assertEquals("off",c.get(MapConfigMigration.MODE));}
 @Test void explicitNewModeWinsOverLegacyEvenWhenConflicting(){var c=CommentedConfig.inMemory();c.set(MapConfigMigration.LEGACY,false);c.set(MapConfigMigration.MODE,"all");assertFalse(MapConfigMigration.migrate(c));GeographyClientConfig.SPEC.correct(c);assertEquals("all",c.get(MapConfigMigration.MODE));}
 @Test void invalidExplicitModeUsesHoverRatherThanLegacyFalse(){var c=CommentedConfig.inMemory();c.set(MapConfigMigration.LEGACY,false);c.set(MapConfigMigration.MODE,"invalid");assertFalse(MapConfigMigration.migrate(c));GeographyClientConfig.SPEC.correct(c);assertEquals("hover",c.get(MapConfigMigration.MODE));}
 @Test void migrationKeepsCustomHudAndOutlineValues(){var c=CommentedConfig.inMemory();c.set(MapConfigMigration.LEGACY,false);c.set("geography_hud.x_offset",240);c.set("geography_hud.scale",1.7);c.set("world_map_geography.world_map_outline_opacity",.62);c.set("world_map_geography.world_map_outline_width",3.0);MapConfigMigration.migrate(c);GeographyClientConfig.SPEC.correct(c);assertEquals(240,c.<Number>get("geography_hud.x_offset").intValue());assertEquals(1.7,c.<Number>get("geography_hud.scale").doubleValue());assertEquals(.62,c.<Number>get("world_map_geography.world_map_outline_opacity").doubleValue());assertEquals(3.0,c.<Number>get("world_map_geography.world_map_outline_width").doubleValue());}
 @Test void preRegistrationMigrationPersistsWithoutCreatingMissingFiles()throws Exception{var file=temp.resolve("client.toml");assertFalse(MapConfigMigration.migrateFile(file));assertFalse(Files.exists(file));Files.writeString(file,"# retained comment\n[world_map_geography]\nworld_map_local_outlines_enabled = false\nworld_map_outline_width = 2.5\n[geography_hud]\nx_offset = 222\n");assertTrue(MapConfigMigration.migrateFile(file));assertFalse(MapConfigMigration.migrateFile(file));try(var c=CommentedFileConfig.builder(file).sync().build()){c.load();assertEquals("off",c.get(MapConfigMigration.MODE));assertEquals(222,c.<Number>get("geography_hud.x_offset").intValue());assertEquals(2.5,c.<Number>get("world_map_geography.world_map_outline_width").doubleValue());}assertTrue(Files.readString(file).contains("retained comment"));}
 @Test void selectedModeSurvivesActualClientConfigSaveAndReload(){var file=temp.resolve("client.toml");try(var c=CommentedFileConfig.builder(file).sync().build()){c.load();GeographyClientConfig.SPEC.setConfig(c);try{GeographyClientConfig.mode(BoundaryMode.ALL);assertEquals(BoundaryMode.ALL,GeographyClientConfig.mode());}finally{GeographyClientConfig.SPEC.setConfig(null);}}try(var reloaded=CommentedFileConfig.builder(file).sync().build()){reloaded.load();GeographyClientConfig.SPEC.setConfig(reloaded);try{assertEquals(BoundaryMode.ALL,GeographyClientConfig.mode());assertEquals("HJ Borders: All",GeographyClientConfig.mode().label());}finally{GeographyClientConfig.SPEC.setConfig(null);}}}
 @Test void newStyleRangesAreFiniteAndBounded(){for(String key:new String[]{"world_map_macro_opacity","world_map_hover_local_opacity","world_map_hover_macro_opacity"}){net.minecraftforge.common.ForgeConfigSpec.ValueSpec v=GeographyClientConfig.SPEC.getSpec().get("world_map_geography."+key);assertTrue(v.test(0D));assertTrue(v.test(1D));assertFalse(v.test(-.01));assertFalse(v.test(1.01));assertFalse(v.test(Double.NaN));}for(String key:new String[]{"world_map_macro_width","world_map_hover_local_width","world_map_hover_macro_width"}){net.minecraftforge.common.ForgeConfigSpec.ValueSpec v=GeographyClientConfig.SPEC.getSpec().get("world_map_geography."+key);assertTrue(v.test(.5D));assertTrue(v.test(4D));assertFalse(v.test(0D));assertFalse(v.test(4.01));}}
}
